package dev.abros.anthub.client;
import com.google.gson.*;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.components.AbstractWidget;
import net.minecraft.client.gui.screens.TitleScreen;
import net.neoforged.neoforge.client.event.ScreenEvent;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.api.distmarker.Dist;
@EventBusSubscriber(modid="anthub",value=Dist.CLIENT)
public final class PilotUiHarness {
 private static int step=-1;private static long at;
 @SubscribeEvent public static void tick(ScreenEvent.Render.Post event){String output=System.getenv("ANTHUB_PILOT_UI");if(output==null||step>=38)return;var mc=Minecraft.getInstance();if(step<0){if(!(event.getScreen() instanceof TitleScreen))return;mc.options.guiScale().set(3);mc.resizeDisplay();CommunityUiHarness.open("normal");var lib=new JsonObject();var profile=new JsonObject();profile.addProperty("active","s1");lib.add("profile",profile);lib.addProperty("limit",12);lib.addProperty("maxBytes",1048576);var rows=new JsonArray();for(int n=0;n<9;n++){var row=new JsonObject();row.addProperty("id","s"+n);row.addProperty("name",n==0?"Строитель":n==1?"Исследователь":"Скин "+n);row.addProperty("hash","0".repeat(64));row.addProperty("slim",n%2==0);rows.add(row);}lib.add("entries",rows);SkinClient.library=lib;SkinClient.busy=false;step=0;at=System.currentTimeMillis()+1500;return;}if(System.currentTimeMillis()<at)return;at=System.currentTimeMillis()+800;try{bounds();var dir=new java.io.File(output);dir.mkdirs();net.minecraft.client.Screenshot.grab(dir,String.format("pilot-%02d.png",step),mc.getMainRenderTarget(),m->{});int theme=step<30?step/6:1;UiPalette.preview(theme);verifyText();SkinClient.busy=false;SkinClient.status="";dev.abros.anthub.network.Protocol.supportedFeatures=java.util.Set.of("skin-order","skin-names");if(step<30)switch(step%6){case 0->mc.setScreen(new CommunityScreen(null,"home",""));case 1->mc.setScreen(new SkinsScreen(null));case 2->mc.setScreen(new QuickSkinsScreen(null));case 3->mc.setScreen(new AccessibilityScreen(null));case 4->{var player=new JsonObject();player.addProperty("uuid",CommunityScreen.me());player.addProperty("name","Исследователь");player.addProperty("online",false);player.addProperty("seen",System.currentTimeMillis()-3600000);player.addProperty("about","Строю города и фермы. Помогу с автоматизацией.");mc.setScreen(new PlayerActionsScreen(null,player,new JsonArray()));}case 5->{var screen=new AccessibilityScreen(null);mc.setScreen(screen);for(var child:screen.children())if(child instanceof net.minecraft.client.gui.components.Button b&&b.getMessage().getString().equals("Поведение")){b.onPress();break;}}}else switch(step){case 30->mc.setScreen(new CommunityScreen(null,"groups",""));case 31->{for(var c:mc.screen.children())if(c instanceof CommunityCard card){card.onPress();break;}}case 32->mc.setScreen(new CommunityScreen(null,"events",""));case 33->mc.setScreen(new CommunityScreen(null,"polls",""));case 34->mc.setScreen(new CommunityScreen(null,"ideas",""));case 35->mc.setScreen(new CommunityScreen(null,"board",""));case 36->mc.setScreen(new NotificationPopup(new CommunityScreen(null,"home","")));case 37->mc.setScreen(new TaskEditScreen(null,"Новая задача",java.util.List.of(new CommunityScreen.Field("title","Название",100),new CommunityScreen.Field("description","Описание",1000)),new JsonObject(),j->{}));}step++;if(step==38){verifyNavigation();System.out.println("ANTHUB_PILOT_OK: home, library, quick grid and settings; five themes");UiPalette.preview(0);mc.setScreen(new ReviewMenu());}}catch(Throwable error){step=38;System.out.println("ANTHUB_PILOT_FAILED");error.printStackTrace();}}
 private static final class ReviewMenu extends net.minecraft.client.gui.screens.Screen {ReviewMenu(){super(net.minecraft.network.chat.Component.literal("AntHub — проверка интерфейса"));}protected void init(){String[] names={"Главная","Библиотека скинов","Быстрая смена","Оформление"};for(int n=0;n<4;n++){final int choice=n;addRenderableWidget(net.minecraft.client.gui.components.Button.builder(net.minecraft.network.chat.Component.literal(names[n]),b->{SkinClient.busy=false;SkinClient.status="";Minecraft.getInstance().setScreen(switch(choice){case 0->new CommunityScreen(this,"home","");case 1->new SkinsScreen(this);case 2->new QuickSkinsScreen(this);default->new AccessibilityScreen(this);});}).bounds(width/2-100,height/2-52+n*28,200,20).build());}}}
 private static void verifyNavigation(){
  var mc=Minecraft.getInstance();var vanilla=new TitleScreen();mc.setScreen(vanilla);
  var home=new CommunityScreen(vanilla,"home","");mc.setScreen(home);
  var groups=new CommunityScreen(null,"groups","");mc.setScreen(groups);
  for(var c:groups.children())if(c instanceof net.minecraft.client.gui.components.EditBox){groups.setFocused(c);if(UiNavigation.handle(groups,259))throw new IllegalStateException("Backspace must edit input");break;}
  groups.setFocused(null);if(!UiNavigation.handle(groups,259)||mc.screen!=home)throw new IllegalStateException("Backspace history failed");
  mc.setScreen(new NotificationPopup(home));if(!UiNavigation.handle(mc.screen,256)||mc.screen!=vanilla)throw new IllegalStateException("Escape must close complete menu");
  if(UiNavigation.handle(vanilla,256))throw new IllegalStateException("Vanilla navigation changed");
  System.out.println("ANTHUB_NAVIGATION_OK: Escape exits; Backspace returns; editable fields and vanilla untouched");
 }
 private static void verifyText(){if(!UiPalette.light())return;for(int c:new int[]{0xFFFFFF,0xBAC6D2,0x79CBA6,0x82B6F2}){int mapped=UiPalette.color(c);if(UiPalette.color(mapped)!=mapped)throw new IllegalStateException("Theme text colour is not stable");if(contrast(mapped,UiKit.surface())<4.5)throw new IllegalStateException("Insufficient light-theme text contrast");}}
 private static double luminance(int c){double v=0;double[] weights={0.0722,0.7152,0.2126};for(int n=0;n<3;n++){double s=((c>>(n*8))&255)/255.0;v+=weights[n]*(s<=0.04045?s/12.92:Math.pow((s+0.055)/1.055,2.4));}return v;}
 private static double contrast(int a,int b){double x=luminance(a),y=luminance(b);return (Math.max(x,y)+0.05)/(Math.min(x,y)+0.05);}
 private static void bounds(){var s=Minecraft.getInstance().screen;var widgets=s.children().stream().filter(c->c instanceof AbstractWidget).map(c->(AbstractWidget)c).filter(w->w.visible).toList();for(var w:widgets)if(w.getX()<0||w.getY()<0||w.getX()+w.getWidth()>s.width||w.getY()+w.getHeight()>s.height)throw new IllegalStateException(s.getClass().getSimpleName()+" out of bounds: "+w.getMessage().getString());for(int i=0;i<widgets.size();i++)for(int j=i+1;j<widgets.size();j++){var a=widgets.get(i);var b=widgets.get(j);if(a.getX()<b.getX()+b.getWidth()&&b.getX()<a.getX()+a.getWidth()&&a.getY()<b.getY()+b.getHeight()&&b.getY()<a.getY()+a.getHeight())throw new IllegalStateException(s.getClass().getSimpleName()+" overlapping: "+a.getMessage().getString()+" / "+b.getMessage().getString());}}
}
